-- GLPI 11 portable long-lived data seed
-- Apply only after GLPI has initialized its own empty schema and defaults.
-- This is not a database recovery dump and does not erase an active instance.
-- It imports normalized people, organization, reference, and asset data only.
-- Tickets, projects, logs, runtime configuration, passwords, tokens, and schema definitions are excluded.
-- Target validated against GLPI 11.0.9 and MariaDB 11.4.

SET NAMES utf8mb4;
SET time_zone = '+00:00';
START TRANSACTION;

